import{_ as a,o as t,c as s,a7 as i}from"./chunks/framework.C4ZIv4ii.js";const n="/falconcms/screenshots/slider-editor.webp",r="/falconcms/screenshots/sliders.webp",m=JSON.parse('{"title":"Falcon Slider","description":"","frontmatter":{},"headers":[],"relativePath":"slider/overview.md","filePath":"slider/overview.md","lastUpdated":1788112837000}'),o={name:"slider/overview.md"};function l(d,e,c,h,p,g){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="falcon-slider" tabindex="-1">Falcon Slider <a class="header-anchor" href="#falcon-slider" aria-label="Permalink to &quot;Falcon Slider&quot;">​</a></h1><p><strong>Falcon Slider</strong> is a layer-based slider builder for FalconCMS — a Slider-Revolution-class engine for hero sliders, banners, and animated showcases. Design every slide on a visual canvas, drop in layers (text, images, buttons, video, countdowns and more), give each layer its own timeline animation, and embed the result anywhere with a shortcode.</p><div class="tip custom-block"><p class="custom-block-title">Pro feature</p><p>Falcon Slider is part of <strong>FalconCMS Pro</strong>. It appears in the admin sidebar once a Pro license is active. See <a href="/falconcms/guide/pro.html">Installing Pro</a>.</p></div><p><img src="'+n+`" alt="The slider editor"></p><p><em>The editor: slide rail along the bottom left, the canvas in the middle, the layer panel on the right, and the animation timeline underneath.</em></p><hr><h2 id="what-you-can-build" tabindex="-1">What you can build <a class="header-anchor" href="#what-you-can-build" aria-label="Permalink to &quot;What you can build&quot;">​</a></h2><ul><li><strong>Full-screen hero sliders</strong> with video or Ken-Burns backgrounds</li><li><strong>Promo banners</strong> with countdown timers and call-to-action buttons</li><li><strong>Animated showcases</strong> where every headline, image and shape animates in on its own schedule</li><li><strong>Auto-playing carousels</strong> with arrows, bullets, progress bars and thumbnail navigation</li></ul><p>Every slider is fully <strong>responsive</strong> — position, size, visibility and font-size can be tuned per device (desktop / tablet / mobile).</p><hr><h2 id="feature-highlights" tabindex="-1">Feature highlights <a class="header-anchor" href="#feature-highlights" aria-label="Permalink to &quot;Feature highlights&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>What&#39;s included</th></tr></thead><tbody><tr><td><strong>Slides</strong></td><td>Unlimited slides, per-slide backgrounds, transitions, whole-slide links</td></tr><tr><td><strong>Backgrounds</strong></td><td>Solid colour, gradient, image, self-hosted video, YouTube / Vimeo, colour &amp; gradient overlays, Ken Burns, parallax</td></tr><tr><td><strong>Layers</strong></td><td>Text, Image, Button, Shape, Icon, Video, Audio, Countdown, HTML/Embed</td></tr><tr><td><strong>Animation</strong></td><td>15 entrance/exit presets, text reveal (typewriter / split), idle loops, per-layer delay·duration·easing</td></tr><tr><td><strong>Navigation</strong></td><td>Arrows, bullets, progress bar, thumbnails, autoplay, loop, pause-on-hover</td></tr><tr><td><strong>Productivity</strong></td><td>Pre-built templates, save-as-template, duplicate, import / export, version history, full-screen live preview</td></tr><tr><td><strong>Performance</strong></td><td>LCP image preload, layout-shift-free rendering, lazy media, subset font &amp; icon loading</td></tr></tbody></table><hr><h2 id="opening-the-editor" tabindex="-1">Opening the editor <a class="header-anchor" href="#opening-the-editor" aria-label="Permalink to &quot;Opening the editor&quot;">​</a></h2><ol><li>Go to <strong>Admin → Falcon Slider</strong></li><li>Click <strong>New Slider</strong>, give it a name, and the full-screen editor opens</li><li>On a brand-new slider the <strong>Pre-built Sliders</strong> gallery opens first — pick a ready-made design or close it to start blank</li></ol><h3 id="the-editor-interface" tabindex="-1">The editor interface <a class="header-anchor" href="#the-editor-interface" aria-label="Permalink to &quot;The editor interface&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌───────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ [← Back] Slides  Pre-built  +Add Layer  Save-as-prebuilt  Revisions │  ← Toolbar</span></span>
<span class="line"><span>│                  [Undo][Redo]  [W][H] [🖥 Tablet Mobile]  [Preview][Save] │</span></span>
<span class="line"><span>├──────────┬──────────────────────────────────────────┬───────────────┤</span></span>
<span class="line"><span>│          │                                          │               │</span></span>
<span class="line"><span>│  Slides  │              Canvas                       │   Settings    │</span></span>
<span class="line"><span>│  rail    │   (live, scaled preview of the slide)     │   (Layers /   │</span></span>
<span class="line"><span>│  (thumbs)│                                          │  Slide / Nav) │</span></span>
<span class="line"><span>│          │                                          │               │</span></span>
<span class="line"><span>└──────────┴──────────────────────────────────────────┴───────────────┘</span></span></code></pre></div><ul><li><strong>Toolbar</strong> — add layers, undo/redo, device switch, <a href="/falconcms/slider/navigation.html#version-history">Revisions</a>, <a href="/falconcms/slider/navigation.html#full-screen-live-preview">Preview</a> and Save</li><li><strong>Slides rail</strong> (left) — thumbnails of every slide; drag to reorder, click to edit</li><li><strong>Canvas</strong> (centre) — a live, scaled preview; drag and resize layers directly</li><li><strong>Settings</strong> (right) — tabs for the selected <strong>Layer</strong>, the <strong>Slide</strong>, and the whole slider (<strong>Nav / Settings</strong>)</li></ul><hr><h2 id="embedding-a-slider" tabindex="-1">Embedding a slider <a class="header-anchor" href="#embedding-a-slider" aria-label="Permalink to &quot;Embedding a slider&quot;">​</a></h2><p>Once saved, a slider is <strong>active</strong> and can be placed on any page in two ways.</p><h3 id="_1-shortcode" tabindex="-1">1. Shortcode <a class="header-anchor" href="#_1-shortcode" aria-label="Permalink to &quot;1. Shortcode&quot;">​</a></h3><p>Use the shortcode in any content, widget, or Blade view that renders shortcodes:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[falcon_slider id=&quot;1&quot;]</span></span></code></pre></div><p><img src="`+r+'" alt="The sliders list"></p><p><em><strong>Admin → Falcon Slider</strong> lists every slider with its shortcode ready to copy, and how many slides it holds.</em></p><p>You can reference a slider by <strong>id</strong> or by <strong>slug</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[falcon_slider slug=&quot;homepage-hero&quot;]</span></span></code></pre></div><h3 id="_2-falcon-builder-element" tabindex="-1">2. Falcon Builder element <a class="header-anchor" href="#_2-falcon-builder-element" aria-label="Permalink to &quot;2. Falcon Builder element&quot;">​</a></h3><p>In <a href="/falconcms/builder/overview.html">Falcon Builder</a>, open the element picker and add the <strong>Falcon Slider</strong> element. In its settings, pick the slider from the dropdown — the live slider renders right on the builder canvas.</p><div class="info custom-block"><p class="custom-block-title">Inactive sliders render nothing</p><p>A slider only outputs on the frontend while it is <strong>active</strong>. An inactive (draft) slider&#39;s shortcode produces no markup.</p></div><hr><h2 id="performance-core-web-vitals" tabindex="-1">Performance &amp; Core Web Vitals <a class="header-anchor" href="#performance-core-web-vitals" aria-label="Permalink to &quot;Performance &amp; Core Web Vitals&quot;">​</a></h2><p>Falcon Slider is built to stay fast and pass Core Web Vitals out of the box:</p><ul><li><strong>LCP</strong> — the first slide&#39;s background image is preloaded with <code>fetchpriority=&quot;high&quot;</code> so it paints immediately.</li><li><strong>CLS</strong> — the slider reserves its exact height (via aspect-ratio or a min-height) before the runtime boots, so nothing shifts on load.</li><li><strong>Lazy media</strong> — off-screen slides don&#39;t download their images or video until they&#39;re about to show.</li><li><strong>Subset fonts &amp; icons</strong> — only the Google Font weights and the exact Material Symbols glyphs a slider actually uses are requested.</li></ul><hr><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/falconcms/slider/slides.html">Slides &amp; Backgrounds</a> — build slides, set backgrounds and transitions</li><li><a href="/falconcms/slider/layers.html">Layers</a> — add and position every layer type</li><li><a href="/falconcms/slider/animations.html">Animations</a> — entrance, reveal and idle-loop animation</li><li><a href="/falconcms/slider/navigation.html">Navigation &amp; Managing</a> — arrows, autoplay, revisions and preview</li></ul>',38)])])}const b=a(o,[["render",l]]);export{m as __pageData,b as default};
